begin; set local timezone='UTC';
do $r$ declare before_hash text; after_hash text; counts record; begin
select md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) order by to_jsonb(t)::text),'')) into before_hash from public.notification_receipts t where student_id in ('b7120000-0000-4000-8000-000000000002','b7120000-0000-4000-8000-000000000003');
for i in 1..2 loop for counts in select * from public.claim_student_notifications_v1(case when i=1 then 'b7120000-0000-4000-8000-000000000002'::uuid else 'b7120000-0000-4000-8000-000000000003'::uuid end) loop
 if counts.new_assignment_count<>0 or counts.deadline_soon_count<>0 then raise exception 'app12_duplicate_receipt';end if; end loop;end loop;
select md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) order by to_jsonb(t)::text),'')) into after_hash from public.notification_receipts t where student_id in ('b7120000-0000-4000-8000-000000000002','b7120000-0000-4000-8000-000000000003');
if before_hash is distinct from after_hash then raise exception 'app12_receipts_changed';end if;
perform set_config('app12.receipt_hash',after_hash,true);end $r$;
select jsonb_build_object('migration',(select jsonb_agg(jsonb_build_object('version',version,'name',name)) from supabase_migrations.schema_migrations where name='order_student_notification_locks'),'receiptHash',current_setting('app12.receipt_hash'),'studentReceiptCounts',(select jsonb_agg(to_jsonb(x)) from(select assignment_id,count(*) from public.notification_receipts where viewer_role='student' and student_id in ('b7120000-0000-4000-8000-000000000002','b7120000-0000-4000-8000-000000000003') group by assignment_id)x),'attempts',(select jsonb_agg(jsonb_build_object('id',id,'assignmentId',assignment_id,'studentId',student_id)) from public.quiz_attempts where student_id in ('b7120000-0000-4000-8000-000000000002','b7120000-0000-4000-8000-000000000003')),'targetStartFirstReceipts',(select count(*) from public.notification_receipts where viewer_role='student' and assignment_id='71a11527-056a-46e1-a2fe-feeb20f5da68')) value; commit;
